/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  if re.search(r'--- page (\\d+) ---',l): page=re.search(r'--- page (\\d+) ---',l).group(1)
  norm=l.replace('\\xa0',' ')
  if re.search(r'govern|construed|New\\s+York',norm,re.I):
   hits.append((page,' '.join(lines[max(0,i-1):min(len(lines),i+3)]).replace('\\xa0',' ')))
 print(f.name[:-4])
 for p,t in hits: print('PAGE',p,t)
PY"

